const body = $input.first().json.body || $input.first().json;

const now = new Date();
const dateStr = now.toISOString().slice(0,10).replace(/-/g,'');
const rand = Math.floor(1000 + Math.random() * 9000);
const leadId = 'VLEAD-' + dateStr + '-' + rand;

const sourceLabel = (body.source === 'calculator') ? 'Calculator Completion' : 'Contact Form';

const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const mo = months[now.getUTCMonth()];
const d  = now.getUTCDate();
const y  = now.getUTCFullYear();
let   h  = now.getUTCHours();
const mi = String(now.getUTCMinutes()).padStart(2,'0');
const ap = h >= 12 ? 'PM' : 'AM';
h = h % 12 || 12;
const readableDate = `${mo} ${d}, ${y} ${h}:${mi} ${ap} UTC`;

return [{
  json: {
    'Lead ID':             leadId,
    'Date Created':        readableDate,
    'Source':              sourceLabel,
    'Name':                (body.name         || '').trim(),
    'Email':               (body.email        || '').trim().toLowerCase(),
    'Phone':               (body.phone        || '').trim(),
    'Business Name':       (body.businessName || '').trim(),
    'Message':             (body.message      || '').trim(),
    'Calc Monthly Leads':  body.calcMonthlyLeads  || '',
    'Calc Avg Value':      body.calcAvgValue      || '',
    'Calc Monthly Loss':   body.calcMonthlyLoss   || '',
    'Status':              'New',
    'Last Contact':        '',
    'Notes':               '',
  }
}];

